    @Nested
    @DisplayName("Tests réussite")
    class Test_Valid {
        static final Map<Integer, String> SYMBOLS = new HashMap<>();

        static {
            SYMBOLS.put(1000, "M");
            SYMBOLS.put(900, "CM");
            SYMBOLS.put(500, "D");
            SYMBOLS.put(400, "CD");
            SYMBOLS.put(100, "C");
            SYMBOLS.put(90, "XC");
            SYMBOLS.put(50, "L");
            SYMBOLS.put(40, "XL");
            SYMBOLS.put(10, "X");
            SYMBOLS.put(9, "IX");
            SYMBOLS.put(5, "V");
            SYMBOLS.put(4, "IV");
            SYMBOLS.put(1, "I");
        }

        @Nested
        @DisplayName("Test : Donner les bonnes valeurs romaines pour des valeurs décimales connues")
        class Test_Donner_Les_Bonnes_Valeurs_Romaines_Pour_Des_Valeurs_Decimales_Connues {

            @Test
            void getRomanFromNumber_standard_values() {
                for (Map.Entry<Integer, String> entry : SYMBOLS.entrySet()) {
                    assertEquals(entry.getValue(), RomanConverter.getRomanFromNumber(entry.getKey()));
                }
            }

            @Test
            void getRomanFromNumber_known_values() {
                assertEquals("VIII", RomanConverter.getRomanFromNumber(8));
                assertEquals("XLIX", RomanConverter.getRomanFromNumber(49));
                assertEquals("CMXLIV", RomanConverter.getRomanFromNumber(944));
                assertEquals("MCDV", RomanConverter.getRomanFromNumber(1405));
                assertEquals("MMMCMI", RomanConverter.getRomanFromNumber(3901));
                assertEquals("MMXXIII", RomanConverter.getRomanFromNumber(2023));
                assertEquals("MMMCMXCIX", RomanConverter.getRomanFromNumber(3999));
            }
        }

        @Nested
        @DisplayName("Test : Donner les bonnes valeurs décimales pour des valeurs romaines connues")
        class Test_Donner_Les_Bonnes_Valeurs_Decimales_Pour_Des_Valeurs_Romaines_Connues {
            @Test
            void getNumberFromRoman_standard_values() {
                for (Map.Entry<Integer, String> entry : SYMBOLS.entrySet()) {
                    assertEquals(entry.getKey(), RomanConverter.getNumberFromRoman(entry.getValue()));
                }
            }

            @Test
            void getNumberFromRoman_known_values() {
                assertEquals(8, RomanConverter.getNumberFromRoman("VIII"));
                assertEquals(49, RomanConverter.getNumberFromRoman("XLIX"));
                assertEquals(944, RomanConverter.getNumberFromRoman("CMXLIV"));
                assertEquals(1405, RomanConverter.getNumberFromRoman("MCDV"));
                assertEquals(3901, RomanConverter.getNumberFromRoman("MMMCMI"));
                assertEquals(2023, RomanConverter.getNumberFromRoman("MMXXIII"));
                assertEquals(3999, RomanConverter.getNumberFromRoman("MMMCMXCIX"));
            }

        }
    }

